"""A tiny, educational, dependency-free validator for a Patient-like FHIR resource.

validate(resource) returns a list of Issue objects; an empty list means valid.

Issue codes:
  - "required":    a mandatory key/value is absent (or a list is empty)
  - "type":        a value has the wrong JSON type
  - "value":       a value is well-typed but violates a constraint
                   (pattern, enum, calendar validity, not-in-future)
  - "unknown-key": a top-level key outside the allowed set
"""

from __future__ import annotations

import re
from dataclasses import dataclass
from datetime import date


@dataclass(frozen=True)
class Issue:
    path: str      # e.g. "", "resourceType", "name[0].family", "birthDate"
    code: str      # "required" | "type" | "value" | "unknown-key"
    message: str


_ID_RE = re.compile(r"^[A-Za-z0-9-]{1,64}$")
_DATE_RE = re.compile(r"^(\d{4})-(\d{2})-(\d{2})$")

_ALLOWED_GENDERS = frozenset({"male", "female", "other", "unknown"})
_ALLOWED_TOP_KEYS = frozenset({"resourceType", "id", "name", "birthDate", "gender"})


def _nonempty_string(value: object) -> bool:
    return isinstance(value, str) and len(value) > 0


def validate(resource: object) -> list[Issue]:
    """Validate a decoded JSON value against the Patient subset schema."""
    if not isinstance(resource, dict):
        return [Issue("", "type", "resource must be a JSON object")]

    issues: list[Issue] = []

    # --- unknown top-level keys -------------------------------------------
    for key in resource.keys():
        if key not in _ALLOWED_TOP_KEYS:
            issues.append(
                Issue(key, "unknown-key", f'unknown top-level key "{key}"')
            )

    # --- resourceType ------------------------------------------------------
    if "resourceType" not in resource:
        issues.append(
            Issue("resourceType", "required", 'missing required field "resourceType"')
        )
    elif not isinstance(resource["resourceType"], str):
        issues.append(
            Issue("resourceType", "type", '"resourceType" must be a string')
        )
    elif resource["resourceType"] != "Patient":
        issues.append(
            Issue("resourceType", "value",
                  '"resourceType" must be "Patient", got '
                  f'{resource["resourceType"]!r}')
        )

    # --- id -----------------------------------------------------------------
    if "id" not in resource:
        issues.append(Issue("id", "required", 'missing required field "id"'))
    else:
        rid = resource["id"]
        if not isinstance(rid, str):
            issues.append(Issue("id", "type", '"id" must be a string'))
        elif not _ID_RE.match(rid):
            issues.append(
                Issue("id", "value",
                      '"id" must match [A-Za-z0-9-]{1,64} (1..64 chars of '
                      f'A-Z, a-z, 0-9 or "-"), got {rid!r}')
            )

    # --- name ---------------------------------------------------------------
    issues.extend(_validate_name(resource))

    # --- birthDate ------------------------------------------------------------
    if "birthDate" in resource:
        bd = resource["birthDate"]
        if not isinstance(bd, str):
            issues.append(Issue("birthDate", "type", '"birthDate" must be a string'))
        else:
            m = _DATE_RE.match(bd)
            if m is None:
                issues.append(
                    Issue("birthDate", "value",
                          f'"birthDate" must match YYYY-MM-DD, got {bd!r}')
                )
            else:
                year, month, day = (int(g) for g in m.groups())
                try:
                    parsed = date(year, month, day)
                except ValueError as exc:
                    issues.append(
                        Issue("birthDate", "value",
                              f'"birthDate" is not a real calendar date: {bd!r} ({exc})')
                    )
                else:
                    if parsed > date.today():
                        issues.append(
                            Issue("birthDate", "value",
                                  f'"birthDate" must not be in the future, got {bd!r}')
                        )

    # --- gender ---------------------------------------------------------------
    if "gender" in resource:
        g = resource["gender"]
        if not isinstance(g, str):
            issues.append(Issue("gender", "type", '"gender" must be a string'))
        elif g not in _ALLOWED_GENDERS:
            allowed = " | ".join(sorted(_ALLOWED_GENDERS))
            issues.append(
                Issue("gender", "value",
                      f'"gender" must be one of {allowed}, got {g!r}')
            )

    return issues


def _validate_name(resource: dict) -> list[Issue]:
    issues: list[Issue] = []

    if "name" not in resource:
        return [Issue("name", "required", 'missing required field "name"')]

    names = resource["name"]
    if not isinstance(names, list):
        return [Issue("name", "type", '"name" must be an array')]

    if len(names) == 0:
        return [Issue("name", "required", '"name" must be a non-empty array')]

    for i, entry in enumerate(names):
        base = f"name[{i}]"
        if not isinstance(entry, dict):
            issues.append(Issue(base, "type", f"{base} must be an object"))
            continue

        # family: required, non-empty string
        if "family" not in entry:
            issues.append(
                Issue(f"{base}.family", "required",
                      f'missing required field "family" in {base}')
            )
        elif not isinstance(entry["family"], str):
            issues.append(
                Issue(f"{base}.family", "type", f"{base}.family must be a string")
            )
        elif len(entry["family"]) == 0:
            issues.append(
                Issue(f"{base}.family", "value",
                      f"{base}.family must be a non-empty string")
            )

        # given: optional, array of non-empty strings
        if "given" in entry:
            given = entry["given"]
            if not isinstance(given, list):
                issues.append(
                    Issue(f"{base}.given", "type", f"{base}.given must be an array")
                )
            else:
                for j, part in enumerate(given):
                    if not isinstance(part, str):
                        issues.append(
                            Issue(f"{base}.given[{j}]", "type",
                                  f"{base}.given[{j}] must be a string")
                        )
                    elif len(part) == 0:
                        issues.append(
                            Issue(f"{base}.given[{j}]", "value",
                                  f"{base}.given[{j}] must be a non-empty string")
                        )

    return issues

